```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string fileName, wordToCount;
    int count = 0;

    // Obtener el nombre del archivo y la palabra a contar
    cout << "Ingrese el nombre del archivo: ";
    cin >> fileName;

    cout << "Ingrese la palabra a contar: ";
    cin >> wordToCount;

    // Abrir el archivo de texto para leerlo línea por línea
    ifstream file(fileName);
    if (!file) {
        cerr << "Error al abrir el archivo: " << fileName << endl;
        return 1;
    }

    string line;
    while (getline(file, line)) {
        // Contar el número de apariciones de la palabra en la línea actual
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != string::npos) {
            count++;
            pos += wordToCount.length();
        }
    }

    file.close();

    // Mostrar el resultado
    cout << "El número de apariciones de la palabra \"" << wordToCount << "\" en el archivo \"" << fileName << "\" es: " << count << endl;

    return 0;
}
```

El programa funciona de la siguiente manera:

1. Solicita al usuario el nombre del archivo y la palabra a contar.
2. Abre el archivo de texto y realiza un bucle para leerlo línea por línea.
3. Para cada línea, utiliza la función `find()` de la biblioteca de cadenas de C++ para buscar la palabra a contar. Si encuentra una aparición, incrementa el contador y actualiza la posición de búsqueda para evitar contar la misma aparición varias veces en la misma línea.
4. Cierra el archivo y muestra el resultado.

